#!/bin/bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)";SDK="/usr/lib/android-sdk";JAR="$SDK/platforms/android-35/android.jar";TOOLS="$SDK/build-tools/35.0.1";OUT="$ROOT/build/manual";GEN="$OUT/gen";CLASSES="$OUT/classes";DEX="$OUT/dex";UNSIGNED="$OUT/unsigned.apk";ALIGNED="$OUT/aligned.apk";FINAL="$ROOT/SafeScan.apk";KEY="$ROOT/safescan.keystore"
rm -rf "$OUT";mkdir -p "$GEN" "$CLASSES" "$DEX";"$TOOLS/aapt" package -f -m -J "$GEN" -M "$ROOT/app/src/main/AndroidManifest.xml" -S "$ROOT/app/src/main/res" -I "$JAR";javac --release 8 -encoding UTF-8 -classpath "$JAR" -d "$CLASSES" $(find "$ROOT/app/src/main/java" -type f -name '*.java'|sort) "$GEN/nl/safescan/local/R.java";"$TOOLS/d8" --lib "$JAR" --min-api 23 --output "$DEX" $(find "$CLASSES" -type f -name '*.class'|sort);"$TOOLS/aapt" package -f -M "$ROOT/app/src/main/AndroidManifest.xml" -S "$ROOT/app/src/main/res" -A "$ROOT/app/src/main/assets" -I "$JAR" -F "$UNSIGNED";(cd "$DEX"&&"$TOOLS/aapt" add "$UNSIGNED" classes.dex);"$TOOLS/zipalign" -f -p 4 "$UNSIGNED" "$ALIGNED";if [ ! -f "$KEY" ];then keytool -genkeypair -keystore "$KEY" -storepass android -keypass android -alias androiddebugkey -keyalg RSA -keysize 2048 -validity 10000 -dname "CN=SafeScan,O=Local,C=NL";fi;"$TOOLS/apksigner" sign --ks "$KEY" --ks-pass pass:android --key-pass pass:android --out "$FINAL" "$ALIGNED";"$TOOLS/apksigner" verify --verbose "$FINAL";echo "$FINAL"
